package solution

type Celsius float64
type Fahrenheit float64

func CToF(c Celsius) Fahrenheit {
	// Convert the defined type to its underlying float64 for the math,
	// then convert the result back into the Fahrenheit defined type.
	f := float64(c)*9/5 + 32
	return Fahrenheit(f)
}

